import { useState, useRef, useEffect } from 'react';
import { Bold, Italic, Underline, List, ListOrdered, AlignLeft, AlignCenter, AlignRight, Link, Image as ImageIcon, Heading1, Heading2, Heading3, Undo, Redo, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import type { I18nText } from '@/lib/i18n-text';
import { createI18nText } from '@/lib/i18n-text';
import { useI18n } from '@/i18n/I18nContext';
import { compressImage } from '@/utils/compress-image';

interface RichTextEditorProps {
  value: I18nText;
  onChange: (val: I18nText) => void;
  placeholder?: string;
  height?: string;
}


const LANGUAGES: { code: 'en' | 'zh' | 'es' | 'ja'; label: string }[] = [
  { code: 'en', label: 'EN' },
  { code: 'zh', label: '中' },
  { code: 'es', label: 'ES' },
  { code: 'ja', label: '日' },
];

export default function RichTextEditor({
  value,
  onChange,
  placeholder = '',
  height = '320px',
}: RichTextEditorProps) {
  const { adminLanguage } = useI18n();
  const [activeLang, setActiveLang] = useState<'en' | 'zh' | 'es' | 'ja'>(
    (adminLanguage as 'en' | 'zh' | 'es' | 'ja') || 'en'
  );
  const [linkDialogOpen, setLinkDialogOpen] = useState(false);
  const [linkUrl, setLinkUrl] = useState('');
  const [imageDialogOpen, setImageDialogOpen] = useState(false);
  const [imageUrl, setImageUrl] = useState('');
  const editorRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // 初始化 + value 变化时同步编辑内容（切换文章 / 外部重置时更新）
  useEffect(() => {
    LANGUAGES.forEach((lang) => {
      const el = editorRefs.current[lang.code];
      if (el && value[lang.code] !== undefined && el.innerHTML !== value[lang.code]) {
        el.innerHTML = value[lang.code] || '';
      }
    });
  }, [value]);

  const execCommand = (command: string, val: string = '') => {
    document.execCommand(command, false, val);
    // 更新对应语言的内容
    const el = editorRefs.current[activeLang];
    if (el) {
      updateValue(activeLang, el.innerHTML);
    }
  };

  const updateValue = (lang: 'en' | 'zh' | 'es' | 'ja', html: string) => {
    onChange({
      ...value,
      [lang]: html,
    });
  };

  const handleInput = (lang: 'en' | 'zh' | 'es' | 'ja') => {
    const el = editorRefs.current[lang];
    if (el) {
      updateValue(lang, el.innerHTML);
    }
  };

  const handleLinkInsert = () => {
    if (!linkUrl.trim()) return;
    execCommand('createLink', linkUrl.trim());
    setLinkUrl('');
    setLinkDialogOpen(false);
  };

  const handleImageInsert = () => {
    if (!imageUrl.trim()) return;
    execCommand('insertImage', imageUrl.trim());
    setImageUrl('');
    setImageDialogOpen(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image must be less than 5MB');
      return;
    }
    try {
      const compressed = await compressImage(file, 1000, 0.7);
      execCommand('insertImage', compressed);
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    e.target.value = '';
  };

  const ToolbarButton = ({ icon: Icon, cmd, arg, title }: { icon: typeof Bold; cmd: string; arg?: string; title: string }) => (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className="h-7 w-7"
      onMouseDown={(e) => {
        e.preventDefault();
        execCommand(cmd, arg);
      }}
      title={title}
    >
      <Icon className="size-3.5" />
    </Button>
  );

  return (
    <div className="border border-border rounded-md overflow-hidden bg-background">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-0.5 p-2 border-b border-border bg-muted/20">
        <ToolbarButton icon={Undo} cmd="undo" title="Undo" />
        <ToolbarButton icon={Redo} cmd="redo" title="Redo" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={Heading1} cmd="formatBlock" arg="h2" title="Heading 1" />
        <ToolbarButton icon={Heading2} cmd="formatBlock" arg="h3" title="Heading 2" />
        <ToolbarButton icon={Heading3} cmd="formatBlock" arg="h4" title="Heading 3" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={Bold} cmd="bold" title="Bold" />
        <ToolbarButton icon={Italic} cmd="italic" title="Italic" />
        <ToolbarButton icon={Underline} cmd="underline" title="Underline" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={List} cmd="insertUnorderedList" title="Bullet List" />
        <ToolbarButton icon={ListOrdered} cmd="insertOrderedList" title="Numbered List" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={AlignLeft} cmd="justifyLeft" title="Align Left" />
        <ToolbarButton icon={AlignCenter} cmd="justifyCenter" title="Align Center" />
        <ToolbarButton icon={AlignRight} cmd="justifyRight" title="Align Right" />
        <div className="w-px h-5 bg-border mx-1" />
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={() => setLinkDialogOpen(true)}
          title="Insert Link"
        >
          <Link className="size-3.5" />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={() => setImageDialogOpen(true)}
          title="Insert Image"
        >
          <ImageIcon className="size-3.5" />
        </Button>
      </div>

      {/* Language Tabs */}
      <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as typeof activeLang)}>
        <TabsList className="w-full justify-start rounded-none border-b border-border bg-transparent h-9 p-0">
          {LANGUAGES.map((lang) => (
            <TabsTrigger
              key={lang.code}
              value={lang.code}
              className="h-9 px-4 text-xs data-[state=active]:bg-background data-[state=active]:shadow-none"
            >
              {lang.label}
            </TabsTrigger>
          ))}
        </TabsList>
        {LANGUAGES.map((lang) => (
          <TabsContent key={lang.code} value={lang.code} className="m-0">
            <div
              ref={(el) => { editorRefs.current[lang.code] = el; }}
              contentEditable
              suppressContentEditableWarning
              onInput={() => handleInput(lang.code)}
              onBlur={() => handleInput(lang.code)}
              className="min-h-[320px] p-4 text-sm leading-relaxed focus:outline-none prose prose-sm dark:prose-invert max-w-none prose-headings:font-semibold prose-a:text-primary"
              style={{ minHeight: height }}
              data-placeholder={placeholder}
            />
          </TabsContent>
        ))}
      </Tabs>

      {/* Link Dialog */}
      <Dialog open={linkDialogOpen} onOpenChange={setLinkDialogOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Insert Link</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <Label>URL</Label>
            <Input
              value={linkUrl}
              onChange={(e) => setLinkUrl(e.target.value)}
              placeholder="https://example.com"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleLinkInsert();
                }
              }}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setLinkDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleLinkInsert}>Insert</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Image Dialog */}
      <Dialog open={imageDialogOpen} onOpenChange={setImageDialogOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Insert Image</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label>Upload Image</Label>
              <Input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="mt-1.5 text-sm"
              />
              <p className="text-xs text-muted-foreground mt-1.5">
                Image will be auto-compressed. Max 5MB.
              </p>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex-1 h-px bg-border" />
              <span className="text-xs text-muted-foreground">OR</span>
              <div className="flex-1 h-px bg-border" />
            </div>
            <div>
              <Label>Image URL</Label>
              <Input
                value={imageUrl}
                onChange={(e) => setImageUrl(e.target.value)}
                placeholder="https://example.com/image.jpg"
                className="mt-1.5"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setImageDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleImageInsert}>Insert URL</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
